import { useMemo } from 'react';

import { FieldProps } from 'components/Filter/types';
import { shouldShowFilterSelectClearIndicator } from 'components/Filter/utils/filterClearableSelectPolicy';
import { Select } from 'components/Form';
import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import { useGoogleAnalytics, usePageFilterData } from 'hooks';
import { Option } from 'models/Filters';

export const WatchTowerBrandField = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const trackGA = useGoogleAnalytics();
  const { dataFilters, defaults } = usePageFilterData(pageName);
  const countryValue = getCurrentValue('country');
  const formValue = getCurrentValue(fieldKey);

  const options: Option[] = useMemo(() => {
    return FilterDataAccessor.getInstance().getOptions(fieldKey, dataFilters, {
      country: countryValue,
    }) as Option[];
  }, [fieldKey, dataFilters, countryValue]);

  const handleValueChange = (option: Option) => {
    if (option?.value == null || option.value === '') {
      onValueChange(fieldKey, { value: null, label: '' });
      return;
    }

    trackGA({
      event_category: 'Brand Select',
      event_action: 'Select',
      event_label: option.value as string,
    });
    onValueChange(fieldKey, option);
  };

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select`}
      label="Brand"
      value={formValue || ''}
      options={options}
      clearable={shouldShowFilterSelectClearIndicator(
        pageName,
        fieldKey,
        String(formValue ?? ''),
        options,
        defaults,
      )}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleValueChange(
          opt === '' ? { value: null, label: '' } : (opt as Option),
        );
      }}
      placeholder="Select a brand"
      searchable
    />
  );
};
